(function () {
    function norm(text) {
        return String(text)
            .replace(/[\u200c\u200e\u200f]/g, '')
            .replace(/\s+/g, ' ')
            .replace(/[:：]\s*$/, '')
            .trim()
            .toLowerCase();
    }

    var index = {};
    window.LITERAL_TRANSLATIONS.forEach(function (item) {
        ['fa', 'en', 'zh'].forEach(function (lang) {
            var value = item[lang];
            if (!value) return;
            var key = norm(value);
            if (key && !index[key]) index[key] = item;
        });
    });

    window.LITERAL_INDEX = index;
    window.normalizeLiteral = norm;
})();


// ============================================
// ترجمه خودکار محتوای داینامیک (مودال‌ها، جدول‌ها، فرم‌ها)
// ============================================
(function () {
    if (!window.MutationObserver) return;

    var queue = [];
    var scheduled = false;

    function currentLanguage() {
        return localStorage.getItem('userLanguage') || 'fa';
    }

    function translateAddedNodes() {
        scheduled = false;

        if (currentLanguage() === 'fa') {
            queue = [];
            return;
        }

        var items = queue;
        queue = [];

        items.forEach(function (node) {
            if (!node || !node.parentNode) return;

            if (node.nodeType === 3) {
                if (typeof translateTextNodes === 'function') translateTextNodes(node.parentNode);
            } else if (node.nodeType === 1) {
                if (typeof translateTextNodes === 'function') translateTextNodes(node);
            }
        });
    }

    var observer = new MutationObserver(function (mutations) {
        for (var i = 0; i < mutations.length; i++) {
            var added = mutations[i].addedNodes;
            for (var j = 0; j < added.length; j++) queue.push(added[j]);
        }

        if (queue.length && !scheduled) {
            scheduled = true;
            setTimeout(translateAddedNodes, 30);
        }
    });

    document.addEventListener('DOMContentLoaded', function () {
        if (document.body) {
            observer.observe(document.body, { childList: true, subtree: true });
        }
    });
})();

